  "indicator_readings": [
    {
      "indicator": "Fechamento",
      "reading": "≈ R$30,2",
      "interpretation": "Preço abaixo das médias móveis de curto e médio prazo; direção imediata de baixa."
    },
    {
      "indicator": "MM20",
      "reading": "≈ R$31,4 (descendente)",
      "interpretation": "MM20 acima do preço e descendente — resistência de curto prazo."
    },
    {
      "indicator": "MM50",
      "reading": "≈ R$32,6 (descendente)",
      "interpretation": "MM50 acima do preço; confirma mudança para viés de baixa no médio prazo."
    },
    {
      "indicator": "MM200",
      "reading": "≈ R$33,2 (plana/levemente descendente)",
      "interpretation": "MM200 acima do preço — nível de resistência importante; estrutura de longo prazo ainda neutra/baixa."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ R$31,0 (descendente)",
      "interpretation": "EMA9 abaixo da EMA21 — momentum de curto prazo negativo."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ R$31,3 (descendente)",
      "interpretation": "Confirmando enfraquecimento recente do preço."
    },
    {
      "indicator": "MACD",
      "reading": "MACD ≈ -0.5; linha de sinal ≈ -0.48; histograma negativo",
      "interpretation": "Momentum vendedor; MACD abaixo da linha de sinal indica pressão de venda."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "Preço tocando banda inferior; bandas relativamente amplas",
      "interpretation": "Volatilidade aumentada e tendência de baixa com continuidade possível enquanto o preço permanecer na banda inferior."
    },
    {
      "indicator": "RSI14",
      "reading": "≈ 30–35",
      "interpretation": "Próximo à zona de sobrevenda — pode provocar repiques técnicos, mas não garante reversão enquanto momentum e médias estiverem baixistas."
    },
    {
      "indicator": "Volume",
      "reading": "Picos em dias de queda",
      "interpretation": "Volume confirma movimentos de baixa (vendas com maior participação)."
    }
  ]
}
